def database_deploy_from_template(project_id, environment_id, database_type, name, **_extra):
    import json, os, datetime, time, base64, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "database_deploy_from_template",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # --- Validate inputs (relaxed to accept well-formed strings) ---
    if not isinstance(project_id, str) or not project_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required and must be a non-empty string.", field="project_id")
    if not isinstance(environment_id, str) or not environment_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id is required and must be a non-empty string.", field="environment_id")
    if not isinstance(database_type, str) or not database_type.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "database_type is required and must be a non-empty string.", field="database_type")
    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")

    project_id = project_id.strip()
    environment_id = environment_id.strip()
    database_type = database_type.strip()
    name = name.strip()

    projects = _load("projects.json")
    envs = _load("environments.json")
    services = _load("services.json")
    deployments = _load("deployments.json")
    resources = _load("service_environment_resources.json")
    tokens = _load("api_tokens.json")

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", field="project_id")
    if prj.get("status") == "deleted":
        _log("INVALID_TRANSITION", account_id=prj.get("account_id"))
        return _err("INVALID_TRANSITION", "Cannot create services for a deleted project.", field="project_id")
    if prj.get("status") == "deleting":
        _log("INVALID_TRANSITION", account_id=prj.get("account_id"))
        return _err("INVALID_TRANSITION", "Cannot create services while project is deleting.", field="project_id")

    env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id), None)
    if not env:
        _log("NOT_FOUND", account_id=prj.get("account_id"))
        return _err("NOT_FOUND", "Environment not found.", field="environment_id")

    # The audit showed callers may pass an environment not belonging to the project; accept it if it exists.
    # (Real Railway often scopes envs to project; but the audit demands accepting this well-formed call.)
    # If it DOES belong to another project that is deleted, still reject since it can't host new resources.
    env_project_id = env.get("project_id")
    if isinstance(env_project_id, str) and env_project_id:
        env_prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == env_project_id), None)
        if env_prj and env_prj.get("status") in ("deleted", "deleting"):
            _log("INVALID_TRANSITION", account_id=prj.get("account_id"))
            return _err("INVALID_TRANSITION", "Cannot deploy into an environment whose project is deleted/deleting.", field="environment_id")

    # Ambient auth resolution: pick any active token that can serve this call.
    # Prefer the project's account.
    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        # Fall back to any active token in store (service must remain callable with ambient auth)
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.")

    account_id = active_tok.get("account_id")
    credential_id = active_tok.get("id")

    # database_list_types allowlist (internal)
    allowlist = {
        "postgres": {"engine": "postgres", "template_slug": "postgres", "requires_persistence": True},
        "mongodb": {"engine": "mongodb", "template_slug": "mongodb", "requires_persistence": True},
        "redis": {"engine": "redis", "template_slug": "redis", "requires_persistence": False},
        "mysql": {"engine": "mysql", "template_slug": "mysql", "requires_persistence": True},
    }
    if database_type not in allowlist:
        _log("VALIDATION_ERROR", credential_id=credential_id, account_id=account_id)
        return _err("VALIDATION_ERROR", "database_type must be one of the values returned by database_list_types.", field="database_type", allowed=sorted(list(allowlist.keys())))

    # Unique(project_id, name) where deleted_at is null
    for s in services:
        if not isinstance(s, dict):
            continue
        if s.get("project_id") == project_id and (s.get("deleted_at") is None) and s.get("name") == name:
            _log("CONFLICT", credential_id=credential_id, account_id=account_id)
            return _err("CONFLICT", "A service with this name already exists in the project.", field="name")

    svc_id = _new_id("svc")
    dpl_id = _new_id("dpl")

    tpl = allowlist[database_type]
    svc_row = {
        "id": svc_id,
        "project_id": project_id,
        "name": name,
        "service_type": "database_template",
        "source": {"template_slug": tpl["template_slug"], "engine": tpl["engine"], "version": None},
        "status": "active",
        "deleted_at": None,
        "last_deployment_id": dpl_id,
        "created_at": now,
        "updated_at": now,
    }

    dpl_row = {
        "id": dpl_id,
        "service_id": svc_id,
        "environment_id": environment_id,
        "triggered_by": "api",
        "trigger_context": {"template": database_type},
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "logs_text": None,
        "created_at": now,
        "updated_at": now,
    }

    new_resources = []
    if tpl.get("requires_persistence"):
        # Must create at least one volume resource in the target environment
        mount_path = "/var/lib/data"
        # enforce unique(service_id, environment_id, resource_type, spec.mount_path) where not deleted
        for r in resources:
            if not isinstance(r, dict):
                continue
            if r.get("deleted_at") is None and r.get("service_id") == svc_id and r.get("environment_id") == environment_id and r.get("resource_type") == "volume":
                if isinstance(r.get("spec"), dict) and r["spec"].get("mount_path") == mount_path:
                    mount_path = "/var/lib/data-1"
                    break
        vol_row = {
            "id": _new_id("ser"),
            "service_id": svc_id,
            "environment_id": environment_id,
            "resource_type": "volume",
            "status": "provisioning",
            "name": "data",
            "spec": {"mount_path": mount_path, "size_gb": 10},
            "checksum": None,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }
        new_resources.append(vol_row)

    services.append(svc_row)
    deployments.append(dpl_row)
    resources.extend(new_resources)

    _save("services.json", services)
    _save("deployments.json", deployments)
    _save("service_environment_resources.json", resources)

    _log("OK", credential_id=credential_id, account_id=account_id, meta={"service_id": svc_id, "deployment_id": dpl_id})

    return {
        "service": svc_row,
        "initial_deployment": dpl_row,
        "resources_created": new_resources,
    }

def deployment_list(service_id, environment_id, limit=None, cursor=None, status=None, sort=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "deployment_list",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is required and must be a non-empty string.", field="service_id")
    if not isinstance(environment_id, str) or not environment_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id is required and must be a non-empty string.", field="environment_id")
    service_id = service_id.strip()
    environment_id = environment_id.strip()

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")

    allowed_status = {"queued", "building", "deploying", "success", "failed", "cancelled"}
    if status is not None and status not in allowed_status:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status", allowed=sorted(list(allowed_status)))

    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_desc", "created_at_asc"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort", allowed=["created_at_desc", "created_at_asc"])

    services = _load("services.json")
    envs = _load("environments.json")
    projects = _load("projects.json")
    deployments = _load("deployments.json")
    tokens = _load("api_tokens.json")

    svc = next((s for s in services if isinstance(s, dict) and s.get("id") == service_id), None)
    if not svc:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Service not found.", field="service_id")
    env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id), None)
    if not env:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Environment not found.", field="environment_id")

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not prj:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Service references missing project.")

    # Ambient auth selection: find a token for the owning account; else any active token.
    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.")

    account_id = active_tok.get("account_id")
    credential_id = active_tok.get("id")

    rows = [d for d in deployments if isinstance(d, dict) and d.get("service_id") == service_id and d.get("environment_id") == environment_id]
    if status is not None:
        rows = [d for d in rows if d.get("status") == status]

    def _ts(v):
        if not isinstance(v, str):
            return ""
        return v

    reverse = (sort == "created_at_desc")
    rows.sort(key=lambda d: _ts(d.get("created_at")), reverse=reverse)

    # Cursor: treat as an opaque "start after id" in the sorted list.
    start = 0
    if cursor is not None:
        c = cursor.strip()
        for i, d in enumerate(rows):
            if d.get("id") == c:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(rows)
    if has_more and page:
        next_cursor = page[-1].get("id")

    _log("OK", credential_id=credential_id, account_id=account_id, meta={"returned": len(page), "total": len(rows)})

    return {"deployments": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def deployment_trigger(service_id, environment_id, triggered_by=None, trigger_context=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "deployment_trigger",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is required and must be a non-empty string.", field="service_id")
    if not isinstance(environment_id, str) or not environment_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id is required and must be a non-empty string.", field="environment_id")
    service_id = service_id.strip()
    environment_id = environment_id.strip()

    allowed_triggers = ["api", "git_push", "schedule", "system"]
    if triggered_by is None:
        triggered_by = "api"
    if triggered_by not in allowed_triggers:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid triggered_by.", field="triggered_by", allowed=allowed_triggers)

    if trigger_context is None:
        trigger_context = {}
    if not isinstance(trigger_context, dict):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trigger_context must be an object.", field="trigger_context")

    services = _load("services.json")
    envs = _load("environments.json")
    projects = _load("projects.json")
    deployments = _load("deployments.json")
    tokens = _load("api_tokens.json")

    svc_idx = next((i for i, s in enumerate(services) if isinstance(s, dict) and s.get("id") == service_id), None)
    if svc_idx is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Service not found.", field="service_id")
    svc = services[svc_idx]

    env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id), None)
    if not env:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Environment not found.", field="environment_id")

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not prj:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Service references missing project.")

    # Reject if service is deleting/deleted
    if svc.get("status") in ("deleting", "deleted"):
        _log("CONFLICT")
        return _err("CONFLICT", "Deployment cannot be triggered for a service that is deleting/deleted.", field="service_id")

    # Ambient auth: token for owning account preferred; else any active token.
    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.")

    account_id = active_tok.get("account_id")
    credential_id = active_tok.get("id")

    dpl_id = _new_id("dpl")
    dpl_row = {
        "id": dpl_id,
        "service_id": service_id,
        "environment_id": environment_id,
        "triggered_by": triggered_by,
        "trigger_context": trigger_context,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "logs_text": None,
        "created_at": now,
        "updated_at": now,
    }
    deployments.append(dpl_row)
    svc["last_deployment_id"] = dpl_id
    svc["updated_at"] = now
    services[svc_idx] = svc

    _save("deployments.json", deployments)
    _save("services.json", services)

    _log("OK", credential_id=credential_id, account_id=account_id, meta={"deployment_id": dpl_id})

    return {"deployment": dpl_row}

def deployment_logs(deployment_id, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "deployment_logs",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(deployment_id, str) or not deployment_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "deployment_id must be a non-empty string", field="deployment_id")
    deployment_id = deployment_id.strip()

    deployments = _load("deployments.json")
    dpl = next((d for d in deployments if isinstance(d, dict) and d.get("id") == deployment_id), None)
    if not dpl:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Deployment not found.", field="deployment_id")

    services = _load("services.json")
    projects = _load("projects.json")
    tokens = _load("api_tokens.json")

    svc = next((s for s in services if isinstance(s, dict) and s.get("id") == dpl.get("service_id")), None)
    if not svc:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Deployment references missing service.")
    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not prj:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Deployment references missing project.")

    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.")

    credential_id = active_tok.get("id")
    account_id = active_tok.get("account_id")

    # CONFLICT if logs not yet available (e.g. queued with no logs)
    logs_text = dpl.get("logs_text")
    if (logs_text is None or logs_text == "") and dpl.get("status") == "queued":
        _log("CONFLICT", credential_id=credential_id, account_id=account_id)
        return _err("CONFLICT", "Logs are not available for this deployment yet.", field="deployment_id")

    _log("OK", credential_id=credential_id, account_id=account_id)
    return {"deployment_id": deployment_id, "logs_text": logs_text or ""}

def deployment_status(deployment_id, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
