        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "domain_delete",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(resource_id, str) or not resource_id:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "resource_id is required", field="resource_id")
    if not re.match(r"^ser_[0-9A-HJKMNP-TV-Z]{10,}$", resource_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "resource_id must match ^ser_[0-9A-HJKMNP-TV-Z]{10,}$", field="resource_id")

    resources = _load("service_environment_resources.json")
    services = _load("services.json")
    projects = _load("projects.json")
    tokens = _load("api_tokens.json")

    idx = next((i for i, r in enumerate(resources) if isinstance(r, dict) and r.get("id") == resource_id), None)
    if idx is None or resources[idx].get("resource_type") != "domain":
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Domain resource not found.", field="resource_id")

    res = resources[idx]
    svc = next((s for s in services if isinstance(s, dict) and s.get("id") == res.get("service_id")), None)
    if not svc:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Domain resource references missing service.")
    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not prj:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Domain resource references missing project.")

    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.")

    # Lifecycle transitions: provisioning/active/failed -> deleting -> deleted
    cur = res.get("status")
    if cur == "deleted" or res.get("deleted_at") is not None:
        _log("OK", credential_id=active_tok.get("id"), account_id=active_tok.get("account_id"), meta={"idempotent": True})
        return {"domain": res}

    if cur == "deleting":
        # complete deletion
        res["status"] = "deleted"
        res["deleted_at"] = res.get("deleted_at") or now
        res["updated_at"] = now
        resources[idx] = res
        _save("service_environment_resources.json", resources)
        _log("OK", credential_id=active_tok.get("id"), account_id=active_tok.get("account_id"))
        return {"domain": res}

    if cur not in ("provisioning", "active", "failed"):
        _log("INVALID_TRANSITION", credential_id=active_tok.get("id"), account_id=active_tok.get("account_id"))
        return _err("INVALID_TRANSITION", f"Cannot delete domain from status '{cur}'.", field="resource_id")

    res["status"] = "deleting"
    res["updated_at"] = now
    resources[idx] = res
    _save("service_environment_resources.json", resources)

    _log("OK", credential_id=active_tok.get("id"), account_id=active_tok.get("account_id"))
    return {"domain": res}

def project_list(limit=None, cursor=None, status=None, account_id=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, credential_id, status_s, started, **meta):
        for fn in ("request_logs.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                logs = _load(fn)
                latency_ms = int((time.time() - started) * 1000)
                row = {
                    "id": "req_" + hashlib.sha256(f"{endpoint}|{started}|{latency_ms}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status_s,
                    "latency_ms": latency_ms,
                    "timestamp": _now(),
                }
                row.update(meta or {})
                if isinstance(logs, list):
                    logs.append(row)
                    _save(fn, logs)
                return

    started = time.time()

    # Defaults
    if limit is None:
        limit = 20
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    # Validate
    if not isinstance(limit, int) or not (1 <= limit <= 100):
        _log("project_list", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log("project_list", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if status is not None and status not in ("active", "deleting", "deleted"):
        _log("project_list", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleting, deleted")
    if account_id is not None and not isinstance(account_id, str):
        _log("project_list", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be a string")
    if sort not in ("created_at", "updated_at", "name"):
        _log("project_list", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name")
    if order not in ("asc", "desc"):
        _log("project_list", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # Ambient auth: choose an active token; enforce rule: projects visible where account_id matches token account
    tokens = _load("api_tokens.json")
    usable = [t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"]
    if not usable:
        _log("project_list", None, "error", started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token configured")

    # If caller supplies account_id filter, must match some active token's account; otherwise default to a usable token
    token = None
    if account_id is not None:
        token = next((t for t in usable if t.get("account_id") == account_id), None)
        if token is None:
            _log("project_list", usable[0].get("id"), "error", started, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Not authorized for requested account_id")
        effective_account = account_id
    else:
        token = usable[0]
        effective_account = token.get("account_id")

    # Cursor decode: opaque base64 of {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                _log("project_list", token.get("id"), "error", started, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = obj["offset"]
        except Exception:
            _log("project_list", token.get("id"), "error", started, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    projects = _load("projects.json")

    # Apply rule + filters: must match authenticated account_id, exclude deleted projects (status != 'deleted')
    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("account_id") != effective_account:
            continue
        if p.get("status") == "deleted":
            continue
        if status is not None and p.get("status") != status:
            continue
        rows.append(p)

    # Sort
    reverse = (order == "desc")

    def _sort_key(p):
        v = p.get(sort)
        if v is None:
            return ""
        return v

    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "projects": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

    _log("project_list", token.get("id"), "ok", started, account_id=effective_account)
    return resp

