            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, account_id=None, meta=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=").lower(),
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "account_id": account_id,
            "latency_ms": latency_ms,
            "ts": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint = "project_info"

    if not isinstance(project_id, str) or not re.match(r"^prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "project_id is missing or not a valid prj_… identifier.", field="project_id")

    projects = _load("projects.json")
    envs = _load("environments.json")
    services = _load("services.json")
    tokens = _load("api_tokens.json")

    visible_account_ids = {t.get("account_id") for t in tokens if t.get("status") == "active" and t.get("provider") == "railway"}
    if not visible_account_ids:
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")

