    if prj.get("account_id") not in visible_account_ids:
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "You do not have access to this project.")

    prj_envs = [e for e in envs if e.get("project_id") == project_id]
    prj_svcs = [s for s in services if s.get("project_id") == project_id and s.get("status") != "deleted"]

    # ensure derived data is consistent with constraints where possible
    derived = {
        "environments": prj_envs,
        "services": prj_svcs,
        "counts": {"environments": len(prj_envs), "services": len(prj_svcs)},
    }

    cred = next((t for t in tokens if t.get("status") == "active" and t.get("provider") == "railway" and t.get("account_id") == prj.get("account_id")), None)
    _log(endpoint, "ok", credential_id=(cred or {}).get("id"), account_id=prj.get("account_id"), started=started)
    return {"project": prj, **derived}

def project_create(name, account_id, description=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "project_create",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if not isinstance(account_id, str) or not account_id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is required and must be a string.", field="account_id")
    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")

    name = name.strip()
    account_id = account_id.strip()

    projects = _load("projects.json")
    envs = _load("environments.json")
    tokens = _load("api_tokens.json")

    # Ambient auth: must have an active token for this account OR at least one active token overall
    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == account_id), None)
    if not active_tok:
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED", account_id=account_id)
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.", field="account_id")

    # Quota (simple): max 50 non-deleted projects per account
    non_deleted = [p for p in projects if isinstance(p, dict) and p.get("account_id") == account_id and p.get("deleted_at") is None]
    if len(non_deleted) >= 50:
        _log("QUOTA_EXCEEDED", credential_id=active_tok.get("id"), account_id=account_id)
        return _err("QUOTA_EXCEEDED", "Project limit reached for this account.", limit=50)

    # unique(account_id, name) where deleted_at is null
    for p in non_deleted:
        if p.get("name") == name:
            _log("CONFLICT", credential_id=active_tok.get("id"), account_id=account_id)
            return _err("CONFLICT", "A project with this name already exists in the account.", field="name")

    prj_id = _new_id("prj")
    env_id = _new_id("env")

    # create a default environment: production
    slug = "production"
    # enforce unique(project_id, slug) (trivial since new project)
    prj_row = {
        "id": prj_id,
        "account_id": account_id,
        "name": name,
        "description": description if description is not None else None,
        "status": "active",
        "default_environment_id": env_id,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    env_row = {
        "id": env_id,
        "project_id": prj_id,
        "name": "Production",
        "slug": slug,
        "is_default": True,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    projects.append(prj_row)
    envs.append(env_row)
    _save("projects.json", projects)
    _save("environments.json", envs)

    _log("OK", credential_id=active_tok.get("id"), account_id=account_id, meta={"project_id": prj_id, "default_environment_id": env_id})
    return {"project": prj_row, "default_environment": env_row}

def project_delete(project_id, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "project_delete",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(project_id, str) or not re.match(r"^prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id or ""):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is missing or not a valid prj_… identifier.", field="project_id")

    projects = _load("projects.json")
    services = _load("services.json")
    resources = _load("service_environment_resources.json")
    deployments = _load("deployments.json")
    tokens = _load("api_tokens.json")

    prj_idx = next((i for i, p in enumerate(projects) if isinstance(p, dict) and p.get("id") == project_id), None)
    if prj_idx is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", field="project_id")
    prj = projects[prj_idx]

    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.")

    account_id = active_tok.get("account_id")
    credential_id = active_tok.get("id")

    status = prj.get("status")
    if status == "deleted":
        _log("CONFLICT", credential_id=credential_id, account_id=account_id)
        return _err("CONFLICT", "Project is already deleted.", field="project_id")
    if status not in ("active", "deleting"):
        _log("INVALID_TRANSITION", credential_id=credential_id, account_id=account_id)
        return _err("INVALID_TRANSITION", f"Cannot delete project from status '{status}'.", field="project_id")

    # Transition active -> deleting -> deleted (second call completes)
    if status == "active":
        prj["status"] = "deleting"
        prj["updated_at"] = now
        projects[prj_idx] = prj
        _save("projects.json", projects)
        _log("OK", credential_id=credential_id, account_id=account_id, meta={"transition": "active->deleting"})
        return {"project": prj}

    # status == deleting: finalize deletion and soft-delete dependents
    prj["status"] = "deleted"
    prj["deleted_at"] = prj.get("deleted_at") or now
    prj["updated_at"] = now
    projects[prj_idx] = prj

    # soft-delete services and their resources; deployments remain as history
    svc_ids = []
    for i, s in enumerate(services):
        if not isinstance(s, dict):
            continue
        if s.get("project_id") != project_id:
            continue
        if s.get("status") != "deleted":
            s["status"] = "deleted"
            s["deleted_at"] = s.get("deleted_at") or now
            s["updated_at"] = now
            services[i] = s
        svc_ids.append(s.get("id"))

    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if r.get("service_id") in svc_ids and r.get("deleted_at") is None:
            r["status"] = "deleted"
            r["deleted_at"] = now
            r["updated_at"] = now
            resources[i] = r

    _save("projects.json", projects)
    _save("services.json", services)
    _save("service_environment_resources.json", resources)
    _save("deployments.json", deployments)

    _log("OK", credential_id=credential_id, account_id=account_id, meta={"transition": "deleting->deleted"})
    return {"project": prj}

