    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "project_environments",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(project_id, str) or not re.match(r"^prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id or ""):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is missing or not a valid prj_… identifier.", field="project_id")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")

    if status is not None and status not in ("active", "archived"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status", allowed=["active", "archived"])
    if is_default is not None and not isinstance(is_default, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_default must be boolean when provided.", field="is_default")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name", "slug"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort", allowed=["created_at", "updated_at", "name", "slug"])
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.", field="order", allowed=["asc", "desc"])

    projects = _load("projects.json")
    envs = _load("environments.json")
    tokens = _load("api_tokens.json")

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", field="project_id")

    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is authorized for the requested project.")

    rows = [e for e in envs if isinstance(e, dict) and e.get("project_id") == project_id]
    if status is not None:
        rows = [e for e in rows if e.get("status") == status]
    if is_default is not None:
        rows = [e for e in rows if bool(e.get("is_default")) == is_default]

    rows.sort(key=lambda x: (x.get(sort) or ""), reverse=(order == "desc"))

    start = 0
    if cursor:
        # Accept either numeric cursor, base64 {"i":n}, or arbitrary (default to 0)
        if cursor.isdigit():
            start = int(cursor)
        else:
            try:
                pad = "=" * (-len(cursor) % 4)
                decoded = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
                obj = json.loads(decoded)
                if isinstance(obj, dict) and isinstance(obj.get("i"), int) and obj["i"] >= 0:
                    start = obj["i"]
            except Exception:
                start = 0

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = str(start + limit) if has_more else None

    _log("OK", credential_id=active_tok.get("id"), account_id=active_tok.get("account_id"), meta={"returned": len(page), "total": len(rows)})
    return {"environments": page, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def service_list(project_id, status=None, service_type=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.fromtimestamp(s, tz=datetime.timezone.utc)
        if isinstance(s, str):
            try:
                # tolerate Z
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except ValueError:
                return None
        return None

    def _log_request(endpoint, credential_id, status_code, latency_ms, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # --- authenticate ambiently: choose any active railway token ---
    tokens = _load("api_tokens.json")
    token = None
    for r in tokens:
        if r.get("provider") == "railway" and r.get("status") == "active":
            token = r
            break
    if not token:
        _log_request("service_list", None, "UNAUTHORIZED", (time.time() - t0) * 1000, {"project_id": project_id})
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")

    # --- validate inputs ---
    if not isinstance(project_id, str) or not re.match(r"^prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid project_id.")

    if status is not None and status not in ("active", "paused", "deleting", "deleted"):
        _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid status filter.")

    if service_type is not None and service_type not in ("app_repo", "app_image", "database_template"):
        _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid service_type filter.")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer in the range 1..100.")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name"):
        _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid sort field.")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid order; must be 'asc' or 'desc'.")

    cursor_offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not re.match(r"^offset:\d+$", cursor):
            _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        cursor_offset = int(cursor.split(":", 1)[1])

    # --- authorize + existence check: project must belong to authenticated account and not be deleted ---
    projects = _load("projects.json")
    project = None
    for p in projects:
        if p.get("id") == project_id and p.get("account_id") == token.get("account_id") and p.get("status") != "deleted":
            project = p
            break
    if not project:
        # If project exists but not visible => NOT_FOUND by tool contract
        _log_request("service_list", token.get("id"), "NOT_FOUND", (time.time() - t0) * 1000, {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.")

    # --- load and filter services ---
    services = _load("services.json")
    rows = []
    for s in services:
        if s.get("project_id") != project_id:
            continue
        if s.get("status") == "deleted":
            continue
        if status is not None and s.get("status") != status:
            continue
        if service_type is not None and s.get("service_type") != service_type:
            continue
        rows.append(s)

    # --- sort ---
    reverse = (order == "desc")

    def _sort_key(r):
        if sort == "name":
            return (r.get("name") or "").lower()
        dt = _parse_dt(r.get(sort))
        return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # if some rows have inconsistent types, treat as validation/server data issue
        _log_request("service_list", token.get("id"), "CONFLICT", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Unable to sort results due to inconsistent stored data.")

    total = len(rows)
    if cursor_offset < 0 or cursor_offset > total:
        _log_request("service_list", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Cursor out of range.")

    page = rows[cursor_offset: cursor_offset + limit]
    next_offset = cursor_offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    resp = {
        "services": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "project_id": project_id,
    }

    _log_request(
        "service_list",
        token.get("id"),
        "OK",
        (time.time() - t0) * 1000,
        {"project_id": project_id, "returned": len(page), "total": total},
    )
    return resp

def service_info(service_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.fromtimestamp(s, tz=datetime.timezone.utc)
        if isinstance(s, str):
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except ValueError:
                return None
        return None

    def _log_request(endpoint, credential_id, status_code, latency_ms, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    tokens = _load("api_tokens.json")
    token = None
    for r in tokens:
        if r.get("provider") == "railway" and r.get("status") == "active":
            token = r
            break
    if not token:
        _log_request("service_info", None, "UNAUTHORIZED", (time.time() - t0) * 1000, {"service_id": service_id})
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")

    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-HJKMNP-TV-Z]{10,}$", service_id):
        _log_request("service_info", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid service_id.")

    services = _load("services.json")
    service = None
    for s in services:
        if s.get("id") == service_id:
            service = s
            break
    if not service or service.get("status") == "deleted":
        _log_request("service_info", token.get("id"), "NOT_FOUND", (time.time() - t0) * 1000, {"service_id": service_id})
        return _err("NOT_FOUND", "Service not found.")

    projects = _load("projects.json")
    project = None
    for p in projects:
        if p.get("id") == service.get("project_id"):
            project = p
            break
    if not project or project.get("status") == "deleted":
        _log_request("service_info", token.get("id"), "NOT_FOUND", (time.time() - t0) * 1000, {"service_id": service_id})
        return _err("NOT_FOUND", "Service not found.")

    if project.get("account_id") != token.get("account_id"):
        _log_request("service_info", token.get("id"), "UNAUTHORIZED", (time.time() - t0) * 1000, {"service_id": service_id})
        return _err("UNAUTHORIZED", "You do not have access to this service.")

    deployments = _load("deployments.json")
    # last deployment per environment (max created_at)
    last_by_env = {}
    for d in deployments:
        if d.get("service_id") != service_id:
            continue
        env_id = d.get("environment_id")
        dt = _parse_dt(d.get("created_at"))
        if env_id is None or dt is None:
            continue
        prev = last_by_env.get(env_id)
        if prev is None or dt > prev["_created_dt"]:
            x = dict(d)
            x["_created_dt"] = dt
            last_by_env[env_id] = x
    # strip helper field
    last_deployments = []
    for env_id, d in last_by_env.items():
        dd = dict(d)
        dd.pop("_created_dt", None)
        last_deployments.append(dd)
    # stable ordering: most recent first
    last_deployments.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), reverse=True)

    resources = _load("service_environment_resources.json")
    attached = []
    for r in resources:
        if r.get("service_id") != service_id:
            continue
        if r.get("status") == "deleted" or r.get("deleted_at") is not None:
            continue
        attached.append(r)

    resp = {
        "service": service,
        "derived": {
            "last_deployments_by_environment": last_deployments,
            "resources": attached,
        },
    }

    _log_request(
        "service_info",
        token.get("id"),
        "OK",
        (time.time() - t0) * 1000,
        {"service_id": service_id, "resources": len(attached), "last_deployments": len(last_deployments)},
    )
    return resp

def service_create_from_repo(project_id, name, repo_url, branch=None, root_directory=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log_request(endpoint, credential_id, status_code, latency_ms, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        # ULID-ish: prefix + base32(48bits time + 80bits rand) simplified with sha
        raw = f"{prefix}:{time.time_ns()}".encode("utf-8")
        b32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256(raw).digest()
        # 16 chars base32
        val = int.from_bytes(h[:10], "big")
        out = []
        for _ in range(16):
            out.append(b32[val % 32])
            val //= 32
        return prefix + "_" + "".join(out)

    t0 = time.time()

    tokens = _load("api_tokens.json")
    token = None
    for r in tokens:
        if r.get("provider") == "railway" and r.get("status") == "active":
            token = r
            break
    if not token:
        _log_request("service_create_from_repo", None, "UNAUTHORIZED", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")

    # validations
    if not isinstance(project_id, str) or not re.match(r"^prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid project_id.")

    if not isinstance(name, str) or not name.strip():
        _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid name.")

    if not isinstance(repo_url, str) or not repo_url.strip():
        _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid repo_url.")

    # basic repo url check (ssh or http(s))
    if not re.match(r"^(https?://|git@)[A-Za-z0-9._:/\-~]+(\.git)?$", repo_url.strip()):
        _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Malformed repo_url.")

    if branch is not None:
        if not isinstance(branch, str) or not branch.strip() or len(branch) > 255:
            _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Invalid branch.")
        # conservative branch name charset
        if not re.match(r"^[A-Za-z0-9._/\-]+$", branch.strip()):
            _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Invalid branch format.")

    if root_directory is not None:
        if not isinstance(root_directory, str) or len(root_directory) > 512:
            _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Invalid root_directory.")
        rd = root_directory.strip()
        if rd in ("", ".", "./"):
            root_directory = None
        else:
            # prevent absolute paths / traversal
            if rd.startswith("/") or ".." in rd.split("/"):
                _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
                return _err("VALIDATION_ERROR", "root_directory must be a safe relative path.")
            if not re.match(r"^[A-Za-z0-9._/\-]+$", rd):
                _log_request("service_create_from_repo", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
                return _err("VALIDATION_ERROR", "Invalid root_directory format.")
            root_directory = rd

    projects = _load("projects.json")
    project = None
    for p in projects:
        if p.get("id") == project_id:
            project = p
            break
    if not project or project.get("account_id") != token.get("account_id") or project.get("status") == "deleted":
        _log_request("service_create_from_repo", token.get("id"), "NOT_FOUND", (time.time() - t0) * 1000, {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.")
    if project.get("status") != "active":
        _log_request("service_create_from_repo", token.get("id"), "INVALID_TRANSITION", (time.time() - t0) * 1000, {"project_status": project.get("status")})
        return _err("INVALID_TRANSITION", "Cannot create services in a project that is not active.")

    envs = _load("environments.json")
    default_env_id = project.get("default_environment_id")
    default_env = None
    if default_env_id:
        for e in envs:
            if e.get("id") == default_env_id and e.get("project_id") == project_id and e.get("status") == "active":
                default_env = e
                break
    if not default_env:
        # fallback: find default environment by flag
        for e in envs:
            if e.get("project_id") == project_id and e.get("is_default") is True and e.get("status") == "active":
                default_env = e
                default_env_id = e.get("id")
                break
    if not default_env:
        _log_request("service_create_from_repo", token.get("id"), "CONFLICT", (time.time() - t0) * 1000, {"project_id": project_id})
        return _err("CONFLICT", "Project has no active default environment.")

    services = _load("services.json")
    # enforce unique(project_id, name) where deleted_at is null
    for s in services:
        if s.get("project_id") == project_id and (s.get("deleted_at") is None) and (s.get("name") == name):
            _log_request("service_create_from_repo", token.get("id"), "CONFLICT", (time.time() - t0) * 1000)
            return _err("CONFLICT", "A service with this name already exists in the project.")

    now = _now()
    svc_id = _gen_id("svc")
    # derive provider/repo crudely; store full url as repo
    provider = "git"
    repo = repo_url.strip()
    if "github.com" in repo:
        provider = "github"
    elif "gitlab.com" in repo:
        provider = "gitlab"
    elif "bitbucket.org" in repo:
        provider = "bitbucket"

    service_row = {
        "id": svc_id,
        "project_id": project_id,
        "name": name,
        "service_type": "app_repo",
        "source": {
            "provider": provider,
            "repo": repo,
            "branch": branch.strip() if isinstance(branch, str) else None,
            "root_dir": root_directory,
        },
        "status": "active",
        "deleted_at": None,
        "last_deployment_id": None,
