def service_create_from_image(project_id, name, image, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log_request(endpoint, credential_id, status_code, latency_ms, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        b32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256(f"{prefix}:{time.time_ns()}".encode("utf-8")).digest()
        val = int.from_bytes(h[:10], "big")
        out = []
        for _ in range(16):
            out.append(b32[val % 32])
            val //= 32
        return prefix + "_" + "".join(out)

    t0 = time.time()

    tokens = _load("api_tokens.json")
    token = None
    for r in tokens:
        if r.get("provider") == "railway" and r.get("status") == "active":
            token = r
            break
    if not token:
        _log_request("service_create_from_image", None, "UNAUTHORIZED", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")

    if not isinstance(project_id, str) or not re.match(r"^prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log_request("service_create_from_image", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid project_id.")

    if not isinstance(name, str) or not name.strip():
        _log_request("service_create_from_image", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid name.")

    if not isinstance(image, str) or not image.strip():
        _log_request("service_create_from_image", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid image.")

    img = image.strip()
    # very basic image ref validation: [registry/]repo[:tag]|@digest
    if not re.match(r"^[a-zA-Z0-9._\-\/]+((:[A-Za-z0-9._\-]{1,128})|(@sha256:[0-9a-fA-F]{64}))?$", img):
        _log_request("service_create_from_image", token.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Malformed image reference.")

    projects = _load("projects.json")
    project = None
    for p in projects:
        if p.get("id") == project_id:
            project = p
            break
    if not project or project.get("account_id") != token.get("account_id") or project.get("status") == "deleted":
        _log_request("service_create_from_image", token.get("id"), "NOT_FOUND", (time.time() - t0) * 1000, {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.")
    if project.get("status") != "active":
        _log_request("service_create_from_image", token.get("id"), "INVALID_TRANSITION", (time.time() - t0) * 1000, {"project_status": project.get("status")})
        return _err("INVALID_TRANSITION", "Cannot create services in a project that is not active.")

    envs = _load("environments.json")
    default_env_id = project.get("default_environment_id")
    default_env = None
    if default_env_id:
        for e in envs:
            if e.get("id") == default_env_id and e.get("project_id") == project_id and e.get("status") == "active":
                default_env = e
                break
    if not default_env:
        for e in envs:
            if e.get("project_id") == project_id and e.get("is_default") is True and e.get("status") == "active":
                default_env = e
                default_env_id = e.get("id")
                break
    if not default_env:
        _log_request("service_create_from_image", token.get("id"), "CONFLICT", (time.time() - t0) * 1000, {"project_id": project_id})
        return _err("CONFLICT", "Project has no active default environment.")

    services = _load("services.json")
    for s in services:
        if s.get("project_id") == project_id and (s.get("deleted_at") is None) and (s.get("name") == name):
            _log_request("service_create_from_image", token.get("id"), "CONFLICT", (time.time() - t0) * 1000)
            return _err("CONFLICT", "A service with this name already exists in the project.")

    # Quota: simple offline rule (not specified in schema); enforce a conservative cap to make QUOTA_EXCEEDED meaningful.
    # cap active/non-deleted services per project to 100
    active_count = 0
    for s in services:
        if s.get("project_id") == project_id and s.get("status") != "deleted" and s.get("deleted_at") is None:
            active_count += 1
    if active_count >= 100:
        _log_request("service_create_from_image", token.get("id"), "QUOTA_EXCEEDED", (time.time() - t0) * 1000, {"project_id": project_id})
        return _err("QUOTA_EXCEEDED", "Service quota exceeded for this project.")

    now = _now()
    svc_id = _gen_id("svc")

    image_name = img
    tag = None
    if "@sha256:" in img:
        # keep digest in tag field for simplicity
        parts = img.split("@", 1)
        image_name = parts[0]
        tag = "@" + parts[1]
    elif ":" in img and "/" in img:
        # last colon after last slash is tag delimiter
        last_slash = img.rfind("/")
        last_colon = img.rfind(":")
        if last_colon > last_slash:
            image_name = img[:last_colon]
            tag = img[last_colon + 1 :]

    service_row = {
        "id": svc_id,
        "project_id": project_id,
        "name": name,
        "service_type": "app_image",
        "source": {
            "image": image_name,
            "tag": tag,
        },
        "status": "active",
        "deleted_at": None,
        "last_deployment_id": None,
        "created_at": now,
        "updated_at": now,
    }

    deployments = _load("deployments.json")
    dep_id = _gen_id("dep")
    dep_row = {
        "id": dep_id,
        "service_id": svc_id,
        "environment_id": default_env_id,
        "triggered_by": "api",
        "trigger_context": {"reason": "initial_create", "image": img},
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "logs_text": None,
        "created_at": now,
        "updated_at": now,
    }

    services.append(service_row)
    deployments.append(dep_row)
    service_row["last_deployment_id"] = dep_id

    _save("services.json", services)
    _save("deployments.json", deployments)

    _log_request(
        "service_create_from_image",
        token.get("id"),
        "OK",
        (time.time() - t0) * 1000,
        {"project_id": project_id, "service_id": svc_id, "deployment_id": dep_id},
    )
    return {"service": service_row, "initial_deployment": dep_row}

def service_update(service_id, name=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, credential_id=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Ambient auth: choose any active railway token (must be able to map to an account_id)
    tokens = _load("api_tokens.json")
    token = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not token:
        _log("service_update", "UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")
    account_id = token.get("account_id")

    # Validate inputs
    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-HJKMNP-TV-Z]{10,}$", service_id):
        _log("service_update", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "service_id is malformed.", field="service_id")

    if name is not None:
        if not isinstance(name, str):
            _log("service_update", "VALIDATION_ERROR", token.get("id"))
            return _err("VALIDATION_ERROR", "name must be a string.", field="name")
        if len(name.strip()) == 0:
            _log("service_update", "VALIDATION_ERROR", token.get("id"))
            return _err("VALIDATION_ERROR", "name cannot be empty.", field="name")
        if len(name) > 128:
            _log("service_update", "VALIDATION_ERROR", token.get("id"))
            return _err("VALIDATION_ERROR", "name is too long.", field="name", max_len=128)

    allowed_status = {"active", "paused", "deleting", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("service_update", "VALIDATION_ERROR", token.get("id"))
            return _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=sorted(allowed_status))

    if name is None and status is None:
        _log("service_update", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "No fields to update. Provide at least one of: name, status.")

    services = _load("services.json")
    service = next((s for s in services if isinstance(s, dict) and s.get("id") == service_id), None)
    if not service:
        _log("service_update", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Service not found.")

    projects = _load("projects.json")
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == service.get("project_id")), None)
    if not project or project.get("account_id") != account_id or project.get("status") == "deleted":
        _log("service_update", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Service not found.")

    # Once project deleted, no new changes (treat as conflict)
    if project.get("status") in ("deleting", "deleted"):
        _log("service_update", "CONFLICT", token.get("id"))
        return _err("CONFLICT", "Cannot update services in a deleting/deleted project.", project_status=project.get("status"))

    # Apply name uniqueness constraint: unique(project_id, name) where deleted_at is null
    if name is not None:
        for s in services:
            if not isinstance(s, dict) or s.get("id") == service_id:
                continue
            if s.get("project_id") == service.get("project_id") and s.get("deleted_at") is None and s.get("name") == name:
                _log("service_update", "CONFLICT", token.get("id"))
                return _err("CONFLICT", "A service with this name already exists in the project.", field="name")

    # Status lifecycle transitions enforced
    if status is not None:
        cur = service.get("status")
        transitions = {
            "active": {"paused", "deleting"},
            "paused": {"active", "deleting"},
            "deleting": {"deleted"},
            "deleted": set()
        }
        if cur not in transitions:
            _log("service_update", "VALIDATION_ERROR", token.get("id"))
            return _err("VALIDATION_ERROR", "Service has invalid current status.", current_status=cur)
        if status != cur:
            if status not in transitions[cur]:
                _log("service_update", "INVALID_TRANSITION", token.get("id"))
                return _err("INVALID_TRANSITION", "Illegal service status transition.", from_status=cur, to_status=status)

    # Perform mutation
    mutated = False
    if name is not None and name != service.get("name"):
        service["name"] = name
        mutated = True

    if status is not None and status != service.get("status"):
        service["status"] = status
        mutated = True
        if status == "deleted":
            service["deleted_at"] = now
        elif status in ("active", "paused", "deleting"):
            # do not clear deleted_at unless it existed and status is not deleted; real system would not "undelete" a deleted service
            if service.get("deleted_at") is not None and service.get("status") != "deleted":
                # if caller tries to move from deleted, transition would have been blocked
                pass

    if not mutated:
        # idempotent update, but still return the current resource
        _log("service_update", "OK", token.get("id"))
        return {"service": service}

    service["updated_at"] = now
    _save("services.json", services)

    _log("service_update", "OK", token.get("id"))
    return {"service": service}

def service_delete(service_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, credential_id=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    tokens = _load("api_tokens.json")
    token = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not token:
        _log("service_delete", "UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")
    account_id = token.get("account_id")

    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-HJKMNP-TV-Z]{10,}$", service_id):
        _log("service_delete", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "service_id is malformed.", field="service_id")

    services = _load("services.json")
    service = next((s for s in services if isinstance(s, dict) and s.get("id") == service_id), None)
    if not service:
        _log("service_delete", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Service not found.")

    projects = _load("projects.json")
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == service.get("project_id")), None)
    if not project or project.get("account_id") != account_id or project.get("status") == "deleted":
        _log("service_delete", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Service not found.")

    cur = service.get("status")
    if cur in ("deleting", "deleted"):
        _log("service_delete", "CONFLICT", token.get("id"))
        return _err("CONFLICT", "Service is already deleting/deleted.", current_status=cur)

    # Enforce lifecycle: active/paused -> deleting
    transitions = {
        "active": {"paused", "deleting"},
        "paused": {"active", "deleting"},
        "deleting": {"deleted"},
        "deleted": set()
    }
    if cur not in transitions or "deleting" not in transitions[cur]:
        _log("service_delete", "INVALID_TRANSITION", token.get("id"))
        return _err("INVALID_TRANSITION", "Service cannot be deleted from its current status.", current_status=cur)

    # Soft-delete dependent resources: transition to deleting->deleted
    resources = _load("service_environment_resources.json")
    changed_resources = 0
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("service_id") != service_id:
            continue
        if r.get("status") == "deleted":
            continue
        # Move to deleting if possible, then to deleted
        r_status = r.get("status")
        if r_status in ("provisioning", "active", "failed"):
            r["status"] = "deleting"
            r["updated_at"] = now
            changed_resources += 1
        # deleting -> deleted
        if r.get("status") == "deleting":
            r["status"] = "deleted"
            r["deleted_at"] = now
            r["updated_at"] = now
            changed_resources += 1

    if changed_resources:
        _save("service_environment_resources.json", resources)

    # Transition service: deleting -> deleted (simulate immediate acceptance + completion)
    service["status"] = "deleting"
    service["updated_at"] = now
    # Complete
    service["status"] = "deleted"
    service["deleted_at"] = now
    service["updated_at"] = now

    _save("services.json", services)

    _log("service_delete", "OK", token.get("id"), deleted_resources=changed_resources)
    return {"service": service}

def service_restart(service_id, environment_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
