        "logs_text": None,
        "created_at": now,
        "updated_at": now
    }
    deployments.append(dep)
    _save("deployments.json", deployments)

    # Update service last_deployment_id
    service["last_deployment_id"] = new_id
    service["updated_at"] = now
    _save("services.json", services)

    _log("service_restart", "OK", token.get("id"), deployment_id=new_id)
    return {
        "result": {
            "accepted": True,
            "action": "restart",
            "service_id": service_id,
            "environment_id": environment_id,
            "operation": {"type": "deployment", "deployment_id": new_id},
            "created_at": now
        }
    }

def tcp_proxy_list(service_id, environment_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, credential_id=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    tokens = _load("api_tokens.json")
    token = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not token:
        _log("tcp_proxy_list", "UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")
    account_id = token.get("account_id")

    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-HJKMNP-TV-Z]{10,}$", service_id):
        _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "service_id is malformed.", field="service_id")
    if not isinstance(environment_id, str) or not re.match(r"^env_[0-9A-HJKMNP-TV-Z]{10,}$", environment_id):
        _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "environment_id is malformed.", field="environment_id")

    allowed_status = {"active", "provisioning", "failed", "deleting", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=sorted(allowed_status))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    sort_allowed = {"created_at", "updated_at", "name"}
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in sort_allowed:
        _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "sort is invalid.", field="sort", allowed=sorted(sort_allowed))

    order_allowed = {"asc", "desc"}
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in order_allowed:
        _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
        return _err("VALIDATION_ERROR", "order is invalid.", field="order", allowed=sorted(order_allowed))

    services = _load("services.json")
    svc = next((s for s in services if isinstance(s, dict) and s.get("id") == service_id), None)
    if not svc:
        _log("tcp_proxy_list", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Service not found.")

    environments = _load("environments.json")
    env = next((e for e in environments if isinstance(e, dict) and e.get("id") == environment_id), None)
    if not env:
        _log("tcp_proxy_list", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Environment not found.")

    if env.get("project_id") != svc.get("project_id"):
        _log("tcp_proxy_list", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Service/environment combination not found.")

    projects = _load("projects.json")
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not project or project.get("account_id") != account_id or project.get("status") == "deleted":
        _log("tcp_proxy_list", "NOT_FOUND", token.get("id"))
        return _err("NOT_FOUND", "Service not found.")

    resources = _load("service_environment_resources.json")
    rows = []
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("service_id") != service_id or r.get("environment_id") != environment_id:
            continue
        if r.get("resource_type") != "tcp_proxy":
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    def _key(v):
        if sort in ("created_at", "updated_at"):
            return v.get(sort) or ""
        # name may be null; sort nulls last in asc, first in desc by using sentinel
        nm = v.get("name")
        return ("" if nm is None else str(nm))

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    # Cursor: opaque string "idx:<offset>"
    offset = 0
    if cursor:
        m = re.match(r"^idx:(\d+)$", cursor)
        if not m:
            _log("tcp_proxy_list", "VALIDATION_ERROR", token.get("id"))
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        offset = int(m.group(1))
        if offset < 0:
            offset = 0

    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = f"idx:{offset + limit}"

    _log("tcp_proxy_list", "OK", token.get("id"), returned=len(page), total=total)
    return {
        "tcp_proxies": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

def tcp_proxy_create(service_id, environment_id, target_port, name=None, **_extra):
    import json, os, datetime, re, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mkid(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        t = int(time.time() * 1000)
        x = t
        s = ""
        while x > 0:
            x, r = divmod(x, 36)
            s = alphabet[r] + s
        s = (s or "0").rjust(10, "0")
        rnd = os.urandom(10)
        tail = "".join(alphabet[b % 36] for b in rnd)
        return f"{prefix}_{s}{tail}"

    def _log(status, credential_id=None, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _mkid("req"),
                "endpoint": "tcp_proxy_create",
                "credential_id": credential_id,
                "account_id": account_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check(credential_id):
        # Lightweight default: 120 requests per rolling 60s per credential, 5000/day.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        day = now - datetime.timedelta(days=1)

        def _parse(ts):
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        last_min = 0
        last_day = 0
        for r in logs:
            if credential_id and r.get("credential_id") != credential_id:
                continue
            tss = r.get("created_at")
            dt = _parse(tss) if isinstance(tss, str) else None
            if not dt:
                continue
            if dt >= window:
                last_min += 1
            if dt >= day:
                last_day += 1
        if last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if last_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    _t0 = time.time()

    # Authenticate ambiently: pick any active Railway token.
    tokens = _load("api_tokens.json")
    if not isinstance(tokens, list):
        tokens = []
    token = next((t for t in tokens if t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not token:
        _log("error", None, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token configured.")
    credential_id = token.get("id")
    account_id = token.get("account_id")

    rl = _rate_limit_check(credential_id)
    if rl:
        _log("error", credential_id, account_id, rl["error"]["code"])
        return rl

    # Validate inputs
    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-Z]{4,}$", service_id):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is malformed.")
    if not isinstance(environment_id, str) or not re.match(r"^env_[0-9A-Z]{4,}$", environment_id):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id is malformed.")
    if not isinstance(target_port, int) or not (1 <= target_port <= 65535):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "target_port must be an integer in range 1..65535.")
    if name is not None and not isinstance(name, str):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a string when provided.")

    projects = _load("projects.json")
    envs = _load("environments.json")
    svcs = _load("services.json")
    resources = _load("service_environment_resources.json")

    if not isinstance(projects, list):
        projects = []
    if not isinstance(envs, list):
        envs = []
    if not isinstance(svcs, list):
        svcs = []
    if not isinstance(resources, list):
        resources = []

    svc = next((s for s in svcs if s.get("id") == service_id), None)
    env = next((e for e in envs if e.get("id") == environment_id), None)
    if not svc or not env:
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Service or environment not found.")
    if svc.get("status") == "deleted" or svc.get("deleted_at") is not None:
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Service not found.")
    if svc.get("project_id") != env.get("project_id"):
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Service and environment do not belong to the same project.")

    proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if not proj or proj.get("account_id") != account_id or proj.get("status") == "deleted":
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Service or environment not accessible.")
    if proj.get("status") != "active":
        _log("error", credential_id, account_id, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot create resources for a project that is not active.")

    # Uniqueness: spec.external_port per service/environment for tcp_proxy
    # Since the tool does not accept an explicit external_port, allocate one deterministically.
    used = set()
    for r in resources:
        if r.get("deleted_at") is not None:
            continue
        if r.get("resource_type") != "tcp_proxy":
            continue
        if r.get("service_id") == service_id and r.get("environment_id") == environment_id:
            sp = r.get("spec") or {}
            if isinstance(sp, dict) and isinstance(sp.get("external_port"), int):
                used.add(sp["external_port"])

    external_port = None
    for p in range(30000, 40001):
        if p not in used:
            external_port = p
            break
    if external_port is None:
        _log("error", credential_id, account_id, "CONFLICT")
        return _err("CONFLICT", "No available external ports for this service/environment.")

    now = _now()
    new_id = _mkid("ser")
    spec = {"external_port": external_port, "internal_port": int(target_port), "protocol": "tcp"}

    row = {
        "id": new_id,
        "service_id": service_id,
        "environment_id": environment_id,
        "resource_type": "tcp_proxy",
        "status": "provisioning",
        "name": name,
        "spec": spec,
        "checksum": hashlib.sha256(json.dumps(spec, sort_keys=True).encode("utf-8")).hexdigest(),
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    resources.append(row)
    _save("service_environment_resources.json", resources)

    _log("ok", credential_id, account_id, None)
    return {"tcp_proxy": row}

