                "account_id": account_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check(credential_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        day = now - datetime.timedelta(days=1)

        def _parse(ts):
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        last_min = 0
        last_day = 0
        for r in logs:
            if credential_id and r.get("credential_id") != credential_id:
                continue
            dt = _parse(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
            if not dt:
                continue
            if dt >= window:
                last_min += 1
            if dt >= day:
                last_day += 1
        if last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if last_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    _t0 = time.time()

    tokens = _load("api_tokens.json")
    if not isinstance(tokens, list):
        tokens = []
    token = next((t for t in tokens if t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not token:
        _log("error", None, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token configured.")
    credential_id = token.get("id")
    account_id = token.get("account_id")

    rl = _rate_limit_check(credential_id)
    if rl:
        _log("error", credential_id, account_id, rl["error"]["code"])
        return rl

    if not isinstance(service_environment_resource_id, str) or not re.match(r"^ser_[0-9A-Z]{4,}$", service_environment_resource_id):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_environment_resource_id is malformed.")

    resources = _load("service_environment_resources.json")
    services = _load("services.json")
    envs = _load("environments.json")
    projects = _load("projects.json")
    if not isinstance(resources, list):
        resources = []
    if not isinstance(services, list):
        services = []
    if not isinstance(envs, list):
        envs = []
    if not isinstance(projects, list):
        projects = []

    idx = None
    row = None
    for i, r in enumerate(resources):
        if r.get("id") == service_environment_resource_id:
            idx = i
            row = r
            break
    if not row or row.get("resource_type") != "tcp_proxy":
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "TCP proxy resource not found.")

    svc = next((s for s in services if s.get("id") == row.get("service_id")), None)
    env = next((e for e in envs if e.get("id") == row.get("environment_id")), None)
    if not svc or not env:
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "TCP proxy resource not accessible.")

    proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if not proj or proj.get("account_id") != account_id or proj.get("status") == "deleted":
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "TCP proxy resource not accessible.")

    status = row.get("status")
    if status == "deleted" or row.get("deleted_at") is not None:
        _log("error", credential_id, account_id, "CONFLICT")
        return _err("CONFLICT", "TCP proxy is already deleted.")

    # Transition rules for resources: provisioning/active/failed -> deleting -> deleted
    allowed = {
        "provisioning": ["active", "failed", "deleting"],
        "active": ["deleting", "failed"],
        "failed": ["provisioning", "deleting"],
        "deleting": ["deleted"],
        "deleted": [],
    }
    if "deleting" not in allowed.get(status, []):
        _log("error", credential_id, account_id, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot delete proxy from status '{status}'.")

    now = _now()
    resources[idx] = dict(row)
    resources[idx]["status"] = "deleting"
    resources[idx]["updated_at"] = now

    # Accept deletion and immediately finalize to deleted (offline backend)
    resources[idx]["status"] = "deleted"
    resources[idx]["deleted_at"] = now
    resources[idx]["updated_at"] = now

    _save("service_environment_resources.json", resources)
    _log("ok", credential_id, account_id, None)
    return {"tcp_proxy": resources[idx]}

def list_service_variables(service_id, environment_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = f"{prefix}:{now}:{os.urandom(16).hex()}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(raw).digest()).decode("ascii").rstrip("=").lower()
        return f"{prefix}_{tok}"

    def _log(status_code, credential_id=None, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("req"),
            "endpoint": "list_service_variables",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Relax regex: datastore uses lower-case ULID-like ids
    if not isinstance(service_id, str) or not service_id.strip() or not re.match(r"^svc_[0-9A-Za-z]{4,}$", service_id.strip()):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is malformed.", field="service_id")
    service_id = service_id.strip()

    if environment_id is not None:
        if not isinstance(environment_id, str) or not environment_id.strip() or not re.match(r"^env_[0-9A-Za-z]{4,}$", environment_id.strip()):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "environment_id is malformed.", field="environment_id")
        environment_id = environment_id.strip()

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")

    services = _load("services.json")
    resources = _load("service_environment_resources.json")
    projects = _load("projects.json")
    tokens = _load("api_tokens.json")

    svc = next((s for s in services if isinstance(s, dict) and s.get("id") == service_id), None)
    if not svc:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Service not found.", field="service_id")
    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not prj:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Service references missing project.")

    active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active" and t.get("account_id") == prj.get("account_id")), None)
    if not active_tok:
        active_tok = next((t for t in tokens if isinstance(t, dict) and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not active_tok:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active credential is available to perform this operation.")

    rows = [
        r for r in resources
        if isinstance(r, dict)
        and r.get("resource_type") == "variable"
        and r.get("service_id") == service_id
        and r.get("deleted_at") is None
        and isinstance(r.get("spec"), dict)
    ]
    if environment_id is not None:
        rows = [r for r in rows if r.get("environment_id") == environment_id]

    # Stable order
    rows.sort(key=lambda r: ((r.get("spec") or {}).get("key") or "", r.get("id") or ""))

    start = 0
    if cursor is not None:
        c = cursor.strip()
        for i, r in enumerate(rows):
            if r.get("id") == c:
                start = i + 1
                break

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    # mask secrets
    out = []
    for r in page:
        rr = dict(r)
        spec = dict(rr.get("spec") or {})
        if spec.get("is_secret") is True and spec.get("value") is not None:
            spec["value"] = "*****"
        rr["spec"] = spec
        out.append(rr)

    _log("OK", credential_id=active_tok.get("id"), account_id=active_tok.get("account_id"), meta={"returned": len(out), "total": len(rows)})
    return {"variables": out, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def variable_set(service_id, environment_id, key, value, **_extra):
    import json, os, datetime, re, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mkid(prefix):
        import os, time
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        t = int(time.time() * 1000)
        x = t
        s = ""
        while x > 0:
            x, r = divmod(x, 36)
            s = alphabet[r] + s
        s = (s or "0").rjust(10, "0")
        rnd = os.urandom(10)
        tail = "".join(alphabet[b % 36] for b in rnd)
        return f"{prefix}_{s}{tail}"

    def _log(status, credential_id=None, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _mkid("req"),
                "endpoint": "variable_set",
                "credential_id": credential_id,
                "account_id": account_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check(credential_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        day = now - datetime.timedelta(days=1)

        def _parse(ts):
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        last_min = 0
        last_day = 0
        for r in logs:
            if credential_id and r.get("credential_id") != credential_id:
                continue
            dt = _parse(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
            if not dt:
                continue
            if dt >= window:
                last_min += 1
            if dt >= day:
                last_day += 1
        if last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if last_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    _t0 = time.time()

    tokens = _load("api_tokens.json")
    if not isinstance(tokens, list):
        tokens = []
    token = next((t for t in tokens if t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not token:
        _log("error", None, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token configured.")
    credential_id = token.get("id")
    account_id = token.get("account_id")

    rl = _rate_limit_check(credential_id)
    if rl:
        _log("error", credential_id, account_id, rl["error"]["code"])
        return rl

    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-Z]{4,}$", service_id):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is malformed.")
    if not isinstance(environment_id, str) or not re.match(r"^env_[0-9A-Z]{4,}$", environment_id):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id is malformed.")
    if not isinstance(key, str) or len(key) < 1:
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "key must be a non-empty string.")
    if not isinstance(value, str):
        _log("error", credential_id, account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "value must be a string.")

    services = _load("services.json")
    envs = _load("environments.json")
    projects = _load("projects.json")
    resources = _load("service_environment_resources.json")
    if not isinstance(services, list):
        services = []
    if not isinstance(envs, list):
        envs = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(resources, list):
        resources = []

    svc = next((s for s in services if s.get("id") == service_id and s.get("status") != "deleted" and s.get("deleted_at") is None), None)
    env = next((e for e in envs if e.get("id") == environment_id), None)
    if not svc or not env:
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Service or environment not found.")
    if env.get("project_id") != svc.get("project_id"):
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Environment not found for this service.")

    proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if not proj or proj.get("account_id") != account_id or proj.get("status") == "deleted":
        _log("error", credential_id, account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Service or environment not accessible.")
    if proj.get("status") != "active":
        _log("error", credential_id, account_id, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot create or modify variables for a project that is not active.")

    # Upsert by (service_id, environment_id, resource_type='variable', spec.key) where deleted_at is null
    now = _now()
    checksum = hashlib.sha256(f"{service_id}|{environment_id}|{key}|{value}".encode("utf-8")).hexdigest()

    found_i = None
    for i, r in enumerate(resources):
        if r.get("resource_type") != "variable":
            continue
        if r.get("deleted_at") is not None or r.get("status") == "deleted":
            continue
        if r.get("service_id") == service_id and r.get("environment_id") == environment_id:
            spec = r.get("spec") if isinstance(r.get("spec"), dict) else {}
            if spec.get("key") == key:
                found_i = i
                break

    if found_i is None:
        # Insert
        row = {
            "id": _mkid("ser"),
            "service_id": service_id,
            "environment_id": environment_id,
            "resource_type": "variable",
            "status": "active",
            "name": key,
            "spec": {"key": key, "value": value, "is_secret": False},
            "checksum": checksum,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }
        resources.append(row)
        _save("service_environment_resources.json", resources)
        _log("ok", credential_id, account_id, None)
        return {"variable": row}

    # Update existing
    row = dict(resources[found_i])
    if not isinstance(row.get("spec"), dict):
        row["spec"] = {}
    row["spec"] = dict(row["spec"])
    row["spec"]["key"] = key
    row["spec"]["value"] = value
    # preserve is_secret if present
    if "is_secret" not in row["spec"]:
        row["spec"]["is_secret"] = False
    row["name"] = row.get("name") or key
    row["checksum"] = checksum
    row["updated_at"] = now
    resources[found_i] = row
    _save("service_environment_resources.json", resources)

    _log("ok", credential_id, account_id, None)
    return {"variable": row}

def variable_delete(service_id, environment_id, key, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Minimal request log support if collection exists
    def _log(status, credential_id=None, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + hashlib.sha256(f"{time.time_ns()}|{os.getpid()}|variable_delete".encode("utf-8")).hexdigest()[:16],
                "endpoint": "variable_delete",
                "status": status,
                "error_code": error_code,
                "credential_id": credential_id,
                "account_id": account_id,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z",
            })
            _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-Z]{4,}$", service_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is malformed", field="service_id")
    if not isinstance(environment_id, str) or not re.match(r"^env_[0-9A-Z]{4,}$", environment_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id is malformed", field="environment_id")
    if not isinstance(key, str) or len(key) < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "key must be a non-empty string", field="key")

    services = _load("services.json")
    envs = _load("environments.json")
    projects = _load("projects.json")
    resources = _load("service_environment_resources.json")
    tokens = _load("api_tokens.json")

    svc = next((s for s in services if s.get("id") == service_id), None)
    env = next((e for e in envs if e.get("id") == environment_id), None)
    if not svc or not env:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "service or environment not found")
    if env.get("project_id") != svc.get("project_id"):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "service/environment scope mismatch")

    proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if not proj or proj.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "project not found")

    # Ambient auth: choose any active token matching the project's account_id
    acct = proj.get("account_id")
    tok = next((t for t in tokens if t.get("account_id") == acct and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not tok:
        _log("error", account_id=acct, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "no active credential available for this account")

    # Cannot mutate if project deleted/deleting? Rules only forbid creation post-delete; allow variable delete unless project deleted.
    # Also refuse if service deleted
    if svc.get("status") in ("deleted", "deleting"):
        _log("error", credential_id=tok.get("id"), account_id=acct, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "cannot modify variables for a deleting/deleted service", service_status=svc.get("status"))

    # Find the variable resource
    idx = None
    row = None
    for i, r in enumerate(resources if isinstance(resources, list) else []):
        if r.get("service_id") == service_id and r.get("environment_id") == environment_id and r.get("resource_type") == "variable":
            if (r.get("deleted_at") is None) and isinstance(r.get("spec"), dict) and r["spec"].get("key") == key:
                idx = i
                row = r
                break
    if row is None:
        _log("error", credential_id=tok.get("id"), account_id=acct, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "variable key not found in this service/environment", key=key)

    # Soft-delete: transition to deleted (resource lifecycle supports deleting->deleted; but variable deletion is immediate here)
    now = datetime.datetime.utcnow().isoformat() + "Z"
    prev = dict(row)
    row["status"] = "deleted"
    row["deleted_at"] = now
    row["updated_at"] = now
    resources[idx] = row
    _save("service_environment_resources.json", resources)

    # Mask secret value on return
    out = dict(row)
    if isinstance(out.get("spec"), dict) and out["spec"].get("is_secret") is True:
        out["spec"] = dict(out["spec"])
        out["spec"]["value"] = "********"

    _log("ok", credential_id=tok.get("id"), account_id=acct)
    return {
        "deleted": True,
        "variable": out,
        "service_id": service_id,
        "environment_id": environment_id,
        "previous": prev
    }

