                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z",
            })
            _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-Z]{4,}$", service_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is malformed", field="service_id")
    if not isinstance(environment_id, str) or not re.match(r"^env_[0-9A-Z]{4,}$", environment_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id is malformed", field="environment_id")
    if not isinstance(variables, dict) or len(variables) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "variables must be a non-empty object", field="variables")
    for k, v in variables.items():
        if not isinstance(k, str) or len(k) == 0:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "all variable keys must be non-empty strings", field="variables")
        if not isinstance(v, str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "all variable values must be strings", field="variables", key=k)

    services = _load("services.json")
    envs = _load("environments.json")
    projects = _load("projects.json")
    resources = _load("service_environment_resources.json")
    tokens = _load("api_tokens.json")

    svc = next((s for s in services if s.get("id") == service_id), None)
    env = next((e for e in envs if e.get("id") == environment_id), None)
    if not svc or not env:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "service or environment not found")
    if env.get("project_id") != svc.get("project_id"):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "service/environment scope mismatch")

    proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if not proj or proj.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "project not found")

    acct = proj.get("account_id")
    tok = next((t for t in tokens if t.get("account_id") == acct and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not tok:
        _log("error", account_id=acct, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "no active credential available for this account")

    if svc.get("status") in ("deleted", "deleting"):
        _log("error", credential_id=tok.get("id"), account_id=acct, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "cannot modify variables for a deleting/deleted service", service_status=svc.get("status"))

    if not isinstance(resources, list):
        resources = []

    # Atomic per environment: validate uniqueness constraints beforehand and stage changes
    now = datetime.datetime.utcnow().isoformat() + "Z"

    # Index existing variables for this scope (non-deleted)
    existing_by_key = {}
    for r in resources:
        if r.get("service_id") == service_id and r.get("environment_id") == environment_id and r.get("resource_type") == "variable" and r.get("deleted_at") is None:
            spec = r.get("spec") if isinstance(r.get("spec"), dict) else None
            if spec and isinstance(spec.get("key"), str):
                existing_by_key[spec["key"]] = r

    staged_new = []
    staged_updates = []

    # Build staged operations
    for k, v in variables.items():
        # checksum for idempotency: hash of key=value
        checksum = hashlib.sha256(f"{k}={v}".encode("utf-8")).hexdigest()
        if k in existing_by_key:
            cur = existing_by_key[k]
            cur_spec = cur.get("spec") if isinstance(cur.get("spec"), dict) else {}
            new_spec = dict(cur_spec)
            new_spec["key"] = k
            new_spec["value"] = v
            # Preserve is_secret flag if present, default false
            if "is_secret" not in new_spec:
                new_spec["is_secret"] = False
            updated = dict(cur)
            updated["spec"] = new_spec
            updated["checksum"] = checksum
            updated["updated_at"] = now
            # ensure active-ish
            if updated.get("status") == "deleted":
                updated["status"] = "active"
                updated["deleted_at"] = None
            staged_updates.append((cur.get("id"), updated))
        else:
            rid = "res_" + hashlib.sha256(f"{time.time_ns()}|{service_id}|{environment_id}|var|{k}".encode("utf-8")).hexdigest()[:20]
            staged_new.append({
                "id": rid,
                "service_id": service_id,
                "environment_id": environment_id,
                "resource_type": "variable",
                "status": "active",
                "name": k,
                "spec": {"key": k, "value": v, "is_secret": False},
                "checksum": checksum,
                "created_at": now,
                "updated_at": now,
                "deleted_at": None
            })

    # Apply all at once
    id_to_index = {r.get("id"): i for i, r in enumerate(resources) if isinstance(r, dict)}
    for rid, updated in staged_updates:
        if rid not in id_to_index:
            _log("error", credential_id=tok.get("id"), account_id=acct, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "variable resource disappeared during update", id=rid)
        resources[id_to_index[rid]] = updated
    if staged_new:
        resources.extend(staged_new)

    _save("service_environment_resources.json", resources)

    # Return resulting set for this scope
    out = []
    for r in resources:
        if r.get("service_id") == service_id and r.get("environment_id") == environment_id and r.get("resource_type") == "variable" and r.get("deleted_at") is None:
            rr = dict(r)
            if isinstance(rr.get("spec"), dict) and rr["spec"].get("is_secret") is True:
                rr["spec"] = dict(rr["spec"])
                rr["spec"]["value"] = "********"
            out.append(rr)

    out.sort(key=lambda x: ((x.get("spec") or {}).get("key") or ""))

    _log("ok", credential_id=tok.get("id"), account_id=acct)
    return {
        "service_id": service_id,
        "environment_id": environment_id,
        "applied": {"created": len(staged_new), "updated": len(staged_updates)},
        "variables": out,
        "total": len(out)
    }

