            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status, credential_id=None, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + hashlib.sha256(f"{time.time_ns()}|{os.getpid()}|variable_copy".encode("utf-8")).hexdigest()[:16],
                "endpoint": "variable_copy",
                "status": status,
                "error_code": error_code,
                "credential_id": credential_id,
                "account_id": account_id,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z",
            })
            _save("request_logs.json", logs)

    if overwrite is None:
        overwrite = False
    if not isinstance(overwrite, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "overwrite must be boolean", field="overwrite")

    if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-Z]{4,}$", service_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is malformed", field="service_id")
    if not isinstance(from_environment_id, str) or not re.match(r"^env_[0-9A-Z]{4,}$", from_environment_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_environment_id is malformed", field="from_environment_id")
    if not isinstance(to_environment_id, str) or not re.match(r"^env_[0-9A-Z]{4,}$", to_environment_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "to_environment_id is malformed", field="to_environment_id")
    if from_environment_id == to_environment_id:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_environment_id and to_environment_id must be different")

    services = _load("services.json")
    envs = _load("environments.json")
    projects = _load("projects.json")
    resources = _load("service_environment_resources.json")
    tokens = _load("api_tokens.json")

    svc = next((s for s in services if s.get("id") == service_id), None)
    env_from = next((e for e in envs if e.get("id") == from_environment_id), None)
    env_to = next((e for e in envs if e.get("id") == to_environment_id), None)

    if not svc or not env_from or not env_to:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "service or environment not found")
    if env_from.get("project_id") != svc.get("project_id") or env_to.get("project_id") != svc.get("project_id"):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "environments must belong to the same project as the service")

    proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if not proj or proj.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "project not found")

    acct = proj.get("account_id")
    tok = next((t for t in tokens if t.get("account_id") == acct and t.get("provider") == "railway" and t.get("status") == "active"), None)
    if not tok:
        _log("error", account_id=acct, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "no active credential available for this account")

    if svc.get("status") in ("deleted", "deleting"):
        _log("error", credential_id=tok.get("id"), account_id=acct, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "cannot modify variables for a deleting/deleted service", service_status=svc.get("status"))

    if not isinstance(resources, list):
        resources = []

    # Collect source variables (non-deleted)
    src = {}
    for r in resources:
        if r.get("service_id") == service_id and r.get("environment_id") == from_environment_id and r.get("resource_type") == "variable" and r.get("deleted_at") is None:
            spec = r.get("spec") if isinstance(r.get("spec"), dict) else None
            if spec and isinstance(spec.get("key"), str):
                src[spec["key"]] = r

    # Destination variables (non-deleted)
    dst = {}
    for r in resources:
        if r.get("service_id") == service_id and r.get("environment_id") == to_environment_id and r.get("resource_type") == "variable" and r.get("deleted_at") is None:
            spec = r.get("spec") if isinstance(r.get("spec"), dict) else None
            if spec and isinstance(spec.get("key"), str):
                dst[spec["key"]] = r

    now = datetime.datetime.utcnow().isoformat() + "Z"

    # Stage (atomic)
    staged_updates = []
    staged_new = []

    for k, rsrc in src.items():
        src_spec = rsrc.get("spec") if isinstance(rsrc.get("spec"), dict) else {}
        v = src_spec.get("value")
        is_secret = bool(src_spec.get("is_secret") is True)
        if not isinstance(v, str):
            # Shouldn't happen given constraints; treat as validation error
            _log("error", credential_id=tok.get("id"), account_id=acct, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "source variable has invalid value type", key=k)

        if k in dst and not overwrite:
            continue

        checksum = hashlib.sha256(f"{k}={v}".encode("utf-8")).hexdigest()
        if k in dst:
            cur = dst[k]
            cur_spec = cur.get("spec") if isinstance(cur.get("spec"), dict) else {}
            new_spec = dict(cur_spec)
            new_spec["key"] = k
            new_spec["value"] = v
            new_spec["is_secret"] = is_secret if "is_secret" in src_spec else bool(new_spec.get("is_secret") is True)
            updated = dict(cur)
            updated["spec"] = new_spec
            updated["checksum"] = checksum
            updated["updated_at"] = now
            staged_updates.append((cur.get("id"), updated))
        else:
            rid = "res_" + hashlib.sha256(f"{time.time_ns()}|{service_id}|{to_environment_id}|var|{k}".encode("utf-8")).hexdigest()[:20]
            staged_new.append({
                "id": rid,
                "service_id": service_id,
                "environment_id": to_environment_id,
                "resource_type": "variable",
                "status": "active",
                "name": k,
                "spec": {"key": k, "value": v, "is_secret": is_secret},
                "checksum": checksum,
                "created_at": now,
                "updated_at": now,
                "deleted_at": None
            })

    # Apply
    id_to_index = {r.get("id"): i for i, r in enumerate(resources) if isinstance(r, dict)}
    for rid, updated in staged_updates:
        if rid not in id_to_index:
            _log("error", credential_id=tok.get("id"), account_id=acct, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "destination variable resource disappeared during update", id=rid)
        resources[id_to_index[rid]] = updated
    if staged_new:
        resources.extend(staged_new)

    _save("service_environment_resources.json", resources)

    # Return destination set
    out = []
    for r in resources:
        if r.get("service_id") == service_id and r.get("environment_id") == to_environment_id and r.get("resource_type") == "variable" and r.get("deleted_at") is None:
            rr = dict(r)
            if isinstance(rr.get("spec"), dict) and rr["spec"].get("is_secret") is True:
                rr["spec"] = dict(rr["spec"])
                rr["spec"]["value"] = "********"
            out.append(rr)
    out.sort(key=lambda x: ((x.get("spec") or {}).get("key") or ""))

    _log("ok", credential_id=tok.get("id"), account_id=acct)
    return {
        "service_id": service_id,
        "from_environment_id": from_environment_id,
        "to_environment_id": to_environment_id,
        "overwrite": overwrite,
        "applied": {"created": len(staged_new), "updated": len(staged_updates), "skipped": max(0, len(src) - (len(staged_new) + len(staged_updates)))},
        "variables": out,
        "total": len(out)
    }

def configure_api_token(account_id, provider=None, token=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status, credential_id=None, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + hashlib.sha256(f"{time.time_ns()}|{os.getpid()}|configure_api_token".encode("utf-8")).hexdigest()[:16],
                "endpoint": "configure_api_token",
                "status": status,
                "error_code": error_code,
                "credential_id": credential_id,
                "account_id": account_id,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z",
            })
            _save("request_logs.json", logs)

    if not isinstance(account_id, str) or not account_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is required", field="account_id")
    if provider is None:
        provider = "railway"
    if provider != "railway":
        _log("error", account_id=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "provider must be 'railway'", field="provider")
    if not isinstance(token, str) or len(token) < 1:
        _log("error", account_id=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "token is required", field="token")

    # "Validate" token offline: basic plausibility only; mark invalid if too short.
    # Store ciphertext placeholder (never plaintext).
    now = datetime.datetime.utcnow().isoformat() + "Z"
    token_last4 = token[-4:] if len(token) >= 4 else token.rjust(4, "*")

    is_valid = True
    # Simple plausibility: Railway tokens tend to be long; treat very short tokens as invalid.
    if len(token) < 12:
        is_valid = False

    token_ciphertext = "enc_" + hashlib.sha256(("railway|" + token).encode("utf-8")).hexdigest()

    api_tokens = _load("api_tokens.json")
    if not isinstance(api_tokens, list):
        api_tokens = []

    # Upsert by (account_id, provider)
    existing = None
    for r in api_tokens:
        if r.get("account_id") == account_id and r.get("provider") == provider:
            # Prefer non-revoked row if multiple exist
            if existing is None or (existing.get("status") == "revoked" and r.get("status") != "revoked"):
                existing = r

    # Enforce unique(account_id, provider) WHERE status='active'
    if is_valid:
        for r in api_tokens:
            if r.get("account_id") == account_id and r.get("provider") == provider and r.get("status") == "active":
                r["status"] = "revoked"
                r["updated_at"] = now

    if existing is None:
        rid = "tok_" + hashlib.sha256(f"{time.time_ns()}|{account_id}|{provider}".encode("utf-8")).hexdigest()[:20]
        row = {
            "id": rid,
            "account_id": account_id,
            "provider": provider,
            "token_ciphertext": token_ciphertext,
            "token_last4": token_last4[-4:],
            "status": "active" if is_valid else "invalid",
            "validated_at": now,
            "created_at": now,
            "updated_at": now
        }
        api_tokens.append(row)
        _save("api_tokens.json", api_tokens)
        _log("ok" if is_valid else "error", credential_id=rid, account_id=account_id, error_code=None if is_valid else "UNAUTHORIZED")
        if not is_valid:
            return _err("UNAUTHORIZED", "token could not be validated", provider=provider, token_last4=row["token_last4"])
        return {k: v for k, v in row.items() if k != "token_ciphertext"}
    else:
        # Update existing row in place
        idx = None
        for i, r in enumerate(api_tokens):
            if r.get("id") == existing.get("id"):
                idx = i
                break
        if idx is None:
            _log("error", account_id=account_id, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "existing token record not found for update")

        existing = dict(existing)
        existing["token_ciphertext"] = token_ciphertext
        existing["token_last4"] = token_last4[-4:]
        existing["status"] = "active" if is_valid else "invalid"
        existing["validated_at"] = now
        existing["updated_at"] = now
        api_tokens[idx] = existing
        _save("api_tokens.json", api_tokens)

        _log("ok" if is_valid else "error", credential_id=existing.get("id"), account_id=account_id, error_code=None if is_valid else "UNAUTHORIZED")
        if not is_valid:
            return _err("UNAUTHORIZED", "token could not be validated", provider=provider, token_last4=existing["token_last4"])
        return {k: v for k, v in existing.items() if k != "token_ciphertext"}

def volume_list(project_id, environment_id=None, service_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, credential_id, status_code, error_code=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "rlog_" + hashlib.sha1(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16],
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log("volume_list", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed.")
    if environment_id is not None:
        if not isinstance(environment_id, str) or not re.match(r"^env_[0-9A-HJKMNP-TV-Z]{10,}$", environment_id):
            _log("volume_list", None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "environment_id is malformed.")
    if service_id is not None:
        if not isinstance(service_id, str) or not re.match(r"^svc_[0-9A-HJKMNP-TV-Z]{10,}$", service_id):
            _log("volume_list", None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "service_id is malformed.")
    if status is not None:
        if status not in ["active", "provisioning", "failed", "deleting", "deleted"]:
            _log("volume_list", None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, provisioning, failed, deleting, deleted.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("volume_list", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        _log("volume_list", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "-created_at"
    if sort not in ["created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"]:
        _log("volume_list", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, -created_at, updated_at, -updated_at, name, -name.")

    # Ambient auth: pick any active railway token; if none, unauthorized
    tokens = _load("api_tokens.json")
    token = None
    for t in tokens:
        if t.get("provider") == "railway" and t.get("status") == "active":
            token = t
            break
    if token is None:
        _log("volume_list", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")

    account_id = token.get("account_id")

    projects = _load("projects.json")
    project = None
    for p in projects:
        if p.get("id") == project_id:
            project = p
            break
    if project is None or project.get("status") == "deleted":
        _log("volume_list", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")
    if project.get("account_id") != account_id:
        _log("volume_list", token.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to this project.")

    envs = _load("environments.json")
    svcs = _load("services.json")
    sers = _load("service_environment_resources.json")

    # Build allowed env/service ids within project
    env_by_id = {e.get("id"): e for e in envs if e.get("project_id") == project_id}
    svc_by_id = {s.get("id"): s for s in svcs if s.get("project_id") == project_id}

    if environment_id is not None and environment_id not in env_by_id:
        # invalid reference (malformed already checked)
        _log("volume_list", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "environment_id does not belong to the given project.", project_id=project_id)
    if service_id is not None and service_id not in svc_by_id:
        _log("volume_list", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id does not belong to the given project.", project_id=project_id)

    # Filter volumes: only non-deleted volumes returned by business rule
    rows = []
    for r in sers:
        if r.get("resource_type") != "volume":
            continue
        if r.get("deleted_at") is not None or r.get("status") == "deleted":
            continue
        sid = r.get("service_id")
        eid = r.get("environment_id")
        if sid not in svc_by_id or eid not in env_by_id:
            continue
        if environment_id is not None and eid != environment_id:
            continue
        if service_id is not None and sid != service_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # Sorting
    reverse = False
    key = sort
    if sort.startswith("-"):
        reverse = True
        key = sort[1:]

    def _dt(v):
        # ISO sort-safe
        if v is None:
            return ""
        return str(v)

    if key in ("created_at", "updated_at"):
        rows.sort(key=lambda x: _dt(x.get(key)), reverse=reverse)
    elif key == "name":
        rows.sort(key=lambda x: ("" if x.get("name") is None else str(x.get("name")).lower(), x.get("id")), reverse=reverse)

    # Cursor pagination: opaque base64 json {"o": offset, "h": hash}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cobj = json.loads(raw.decode("utf-8"))
            if not isinstance(cobj, dict) or "o" not in cobj:
                raise ValueError("bad cursor")
            offset = int(cobj["o"])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("volume_list", token.get("id"), 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid or expired.")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        nxt = {"o": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(nxt, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "volumes": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor
        }
    }
    _log("volume_list", token.get("id"), 200, None)
    return resp

def volume_create(service_id, environment_id, name, spec, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
