        _log("volume_create", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")
    account_id = token.get("account_id")

    services = _load("services.json")
    environments = _load("environments.json")
    projects = _load("projects.json")
    sers = _load("service_environment_resources.json")

    svc = next((s for s in services if s.get("id") == service_id), None)
    env = next((e for e in environments if e.get("id") == environment_id), None)
    if svc is None:
        _log("volume_create", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Service not found.")
    if env is None:
        _log("volume_create", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Environment not found.")
    if svc.get("project_id") != env.get("project_id"):
        _log("volume_create", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id and environment_id must belong to the same project.")

    project = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if project is None or project.get("status") == "deleted":
        _log("volume_create", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Owning project not found.")
    if project.get("account_id") != account_id:
        _log("volume_create", token.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to the owning project.")
    if project.get("status") != "active":
        _log("volume_create", token.get("id"), 409, "CONFLICT")
        return _err("CONFLICT", "Cannot create resources for a project that is not active.")
    if svc.get("status") in ("deleting", "deleted"):
        _log("volume_create", token.get("id"), 409, "CONFLICT")
        return _err("CONFLICT", "Cannot create volumes for a service that is deleting/deleted.")

    # Uniqueness: (service_id, environment_id, resource_type, spec.mount_path) where deleted_at is null
    for r in sers:
        if r.get("resource_type") == "volume" and r.get("service_id") == service_id and r.get("environment_id") == environment_id:
            if r.get("deleted_at") is None and (r.get("spec") or {}).get("mount_path") == mount_path:
                _log("volume_create", token.get("id"), 409, "CONFLICT")
                return _err("CONFLICT", "A volume with this mount_path already exists for the service/environment.", mount_path=mount_path)

    # Create resource
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        h = hashlib.sha1(f"{prefix}|{ts}|{time.time_ns()}".encode("utf-8")).digest()
        out = []
        for b in h[:16]:
            out.append(alphabet[b % 32])
        return f"{prefix}_{''.join(out)}"

    rid = _new_id("ser")
    row = {
        "id": rid,
        "service_id": service_id,
        "environment_id": environment_id,
        "resource_type": "volume",
        "status": "provisioning",
        "name": name.strip(),
        "spec": spec,
        "checksum": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }
    sers.append(row)
    _save("service_environment_resources.json", sers)

    _log("volume_create", token.get("id"), 201, None)
    return {"volume": row}

def volume_update(volume_id, name=None, spec=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, credential_id, status_code, error_code=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "rlog_" + hashlib.sha1(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16],
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(volume_id, str) or not re.match(r"^ser_[0-9A-HJKMNP-TV-Z]{10,}$", volume_id):
        _log("volume_update", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "volume_id is malformed.")
    if name is None and spec is None:
        _log("volume_update", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one of name or spec must be provided.")
    if name is not None and (not isinstance(name, str) or len(name.strip()) < 1):
        _log("volume_update", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if spec is not None and not isinstance(spec, dict):
        _log("volume_update", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spec must be an object.")

    tokens = _load("api_tokens.json")
    token = next((t for t in tokens if t.get("provider") == "railway" and t.get("status") == "active"), None)
    if token is None:
        _log("volume_update", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")
    account_id = token.get("account_id")

    sers = _load("service_environment_resources.json")
    services = _load("services.json")
    environments = _load("environments.json")
    projects = _load("projects.json")

    idx = None
    vol = None
    for i, r in enumerate(sers):
        if r.get("id") == volume_id and r.get("resource_type") == "volume":
            idx = i
            vol = r
            break
    if vol is None:
        _log("volume_update", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Volume not found.")

    svc = next((s for s in services if s.get("id") == vol.get("service_id")), None)
    env = next((e for e in environments if e.get("id") == vol.get("environment_id")), None)
    if svc is None or env is None:
        _log("volume_update", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Owning service/environment not found.")
    project = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if project is None or project.get("status") == "deleted":
        _log("volume_update", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Owning project not found.")
    if project.get("account_id") != account_id:
        _log("volume_update", token.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to the owning project.")

    # Non-updatable states
    if vol.get("status") in ("deleting", "deleted") or vol.get("deleted_at") is not None:
        _log("volume_update", token.get("id"), 409, "CONFLICT")
        return _err("CONFLICT", "Volume cannot be updated in its current state.", status=vol.get("status"))

    # Apply updates with rule: size_gb decreases rejected
    new_vol = dict(vol)

    if name is not None:
        new_vol["name"] = name.strip()

    if spec is not None:
        # Validate required fields if present/changed
        merged = dict(new_vol.get("spec") or {})
        for k, v in spec.items():
            merged[k] = v

        # Ensure mount_path exists
        mount_path = merged.get("mount_path")
        if mount_path is None or not isinstance(mount_path, str) or len(mount_path.strip()) == 0:
            _log("volume_update", token.get("id"), 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "spec.mount_path is required for a volume.")

        size_gb = merged.get("size_gb")
        if size_gb is None or not isinstance(size_gb, int) or size_gb < 1:
            _log("volume_update", token.get("id"), 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "spec.size_gb must be an integer >= 1.")

        old_size = (new_vol.get("spec") or {}).get("size_gb")
        if isinstance(old_size, int) and size_gb < old_size:
            _log("volume_update", token.get("id"), 409, "CONFLICT")
            return _err("CONFLICT", "spec.size_gb cannot be decreased.", old_size_gb=old_size, new_size_gb=size_gb)

        # Uniqueness: mount_path unique per service/environment among non-deleted
        for r in sers:
            if r.get("id") == volume_id:
                continue
            if r.get("resource_type") == "volume" and r.get("service_id") == vol.get("service_id") and r.get("environment_id") == vol.get("environment_id"):
                if r.get("deleted_at") is None and (r.get("spec") or {}).get("mount_path") == mount_path:
                    _log("volume_update", token.get("id"), 409, "CONFLICT")
                    return _err("CONFLICT", "Another volume already uses this mount_path in the service/environment.", mount_path=mount_path)

        new_vol["spec"] = merged

    new_vol["updated_at"] = now
    sers[idx] = new_vol
    _save("service_environment_resources.json", sers)

    _log("volume_update", token.get("id"), 200, None)
    return {"volume": new_vol}

def volume_delete(volume_id, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0078000" if __import__("os").path.isdir("./environment_mix/0078000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, credential_id, status_code, error_code=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "rlog_" + hashlib.sha1(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16],
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(volume_id, str) or not re.match(r"^ser_[0-9A-HJKMNP-TV-Z]{10,}$", volume_id):
        _log("volume_delete", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "volume_id is malformed.")

    tokens = _load("api_tokens.json")
    token = next((t for t in tokens if t.get("provider") == "railway" and t.get("status") == "active"), None)
    if token is None:
        _log("volume_delete", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Railway API token is configured.")
    account_id = token.get("account_id")

    sers = _load("service_environment_resources.json")
    services = _load("services.json")
    environments = _load("environments.json")
    projects = _load("projects.json")
    deployments = _load("deployments.json")

    idx = None
    vol = None
    for i, r in enumerate(sers):
        if r.get("id") == volume_id and r.get("resource_type") == "volume":
            idx = i
            vol = r
            break
    if vol is None:
        _log("volume_delete", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Volume not found.")

    svc = next((s for s in services if s.get("id") == vol.get("service_id")), None)
    env = next((e for e in environments if e.get("id") == vol.get("environment_id")), None)
    if svc is None or env is None:
        _log("volume_delete", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Owning service/environment not found.")
    project = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if project is None or project.get("status") == "deleted":
        _log("volume_delete", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Owning project not found.")
    if project.get("account_id") != account_id:
        _log("volume_delete", token.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to the owning project.")

    # If already deleted, report conflict/not found? In Railway-like APIs, soft-deleted resource is typically not found.
    if vol.get("deleted_at") is not None or vol.get("status") == "deleted":
        _log("volume_delete", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Volume not found.")

    # Reject deletion if a deployment is currently building/deploying for same service/environment
    for d in deployments:
        if d.get("service_id") == vol.get("service_id") and d.get("environment_id") == vol.get("environment_id"):
            if d.get("status") in ("building", "deploying"):
                _log("volume_delete", token.get("id"), 409, "CONFLICT")
                return _err("CONFLICT", "Volume cannot be deleted while a deployment is building/deploying for the same service/environment.", deployment_id=d.get("id"))

    # Transition: active/failed/provisioning -> deleting -> deleted (asynchronously in reality)
    # We'll perform first step to 'deleting' if not already, and if already 'deleting' move to 'deleted' idempotently on repeated call.
    cur = vol.get("status")
    transitions = {
        "provisioning": ["active", "failed", "deleting"],
        "active": ["deleting", "failed"],
        "failed": ["provisioning", "deleting"],
        "deleting": ["deleted"],
        "deleted": []
    }

    updated = dict(vol)
    if cur == "deleting":
        if "deleted" not in transitions.get(cur, []):
            _log("volume_delete", token.get("id"), 409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Volume cannot transition to deleted from its current state.", status=cur)
        updated["status"] = "deleted"
        updated["deleted_at"] = now
        updated["updated_at"] = now
    else:
        if "deleting" not in transitions.get(cur, []):
            _log("volume_delete", token.get("id"), 409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Volume cannot be deleted from its current state.", status=cur)
        updated["status"] = "deleting"
        updated["updated_at"] = now

    sers[idx] = updated
    _save("service_environment_resources.json", sers)

    _log("volume_delete", token.get("id"), 200, None)
    return {"volume": updated}
